INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(25361, 'Luke 22:21', 'Luke', 22, 21, 'خو ګورئ، هغه څوک چې زما سره به خیانت کوي هغه دلته زما سره په دسترخوان ناست دی.', 'خو ګوری، هغه چوک چې زما سره به خیانت کوی هغه دلته زما سره په دسترخوان ناست دی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25362, 'Luke 22:22', 'Luke', 22, 22, 'لکه څنګه چې د خدای له خوا مقرره وه چې د انسان زوی باید مړ شي، خو افسوس د هغه چا په حال چې د هغه سره خیانت کوي.»', 'لکه چنګه چې د خدای له خوا مقرره وه چې د انسان زوی باید مر شی، خو افسوس د هغه چا په حال چې د هغه سره خیانت کوی.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25363, 'Luke 22:23', 'Luke', 22, 23, 'بیا هغوی په خپلو کې یو د بل څخه پوښتنې پیل کړې چې په دوی کې به څوک دا کار کوي. د لویۍ په هکله بحث', 'بیا هغوی په خپلو کې یو د بل چخه پوشتنې پیل کرې چې په دوی کې به چوک دا کار کوی. د لویی په هکله بحث', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25364, 'Luke 22:24', 'Luke', 22, 24, 'بیا د هغوی ترمنځ ناندرۍ پیل شوې چې په دوی کې به څوک د ټولو څخه لوی وګڼل شي.', 'بیا د هغوی ترمنج ناندری پیل شوې چې په دوی کې به چوک د تولو چخه لوی وګنل شی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25365, 'Luke 22:25', 'Luke', 22, 25, 'عیسی هغوی ته وویل: «د غیریهودیانو پاچاهان په خپلو خلکو باداري کوي او واکمنان د خلکو خیرخواه ګڼل کیږي.', 'عیسی هغوی ته وویل: «د غیریهودیانو پاچاهان په خپلو خلکو باداری کوی او واکمنان د خلکو خیرخواه ګنل کیزی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25366, 'Luke 22:26', 'Luke', 22, 26, 'خو تاسو داسې مه اوسئ، بلکې په تاسو کې دې تر ټولو لوی خپل ځان کوچنی وګڼي او مشر دې د خدمتګار په شان وي.', 'خو تاسو داسې مه اوسی، بلکې په تاسو کې دې تر تولو لوی خپل جان کوچنی وګنی او مشر دې د خدمتګار په شان وی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25367, 'Luke 22:27', 'Luke', 22, 27, 'خلک څه فکر کوي چې په دوی دواړو کې کوم یو لوی دی، هغه څوک چې ډوډۍ ته ناست دی او یا هغه څوک چې خدمت کوي؟ په یقین سره هغه څوک چې ډوډۍ ته ناست دی. خو زه ستاسو په منځ کې د یو خدمتګار په شان یم.', 'خلک چه فکر کوی چې په دوی دوارو کې کوم یو لوی دی، هغه چوک چې دودی ته ناست دی او یا هغه چوک چې خدمت کوی؟ په یقین سره هغه چوک چې دودی ته ناست دی. خو زه ستاسو په منج کې د یو خدمتګار په شان یم.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25368, 'Luke 22:28', 'Luke', 22, 28, 'خو تاسو زما د ازمېښتونو په وخت کې زما سره ولاړ وئ.', 'خو تاسو زما د ازمېشتونو په وخت کې زما سره ولار وی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25369, 'Luke 22:29', 'Luke', 22, 29, 'لکه څنګه چې زما پلار ماته د پاچاهۍ حق راکړی دی، زه هم تاسو ته دا حق درکوم.', 'لکه چنګه چې زما پلار ماته د پاچاهی حق راکری دی، زه هم تاسو ته دا حق درکوم.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25370, 'Luke 22:30', 'Luke', 22, 30, 'تاسو به زما په پاچاهۍ کې زما په دسترخوان خورئ او څښئ او په تختونو باندې به کښېنئ او د اسراییلو په دولسو قبیلو باندې به حکومت کوئ.» د پطروس د انکار په هکله د عیسی پېشګويي (متي ۲۶‏:‌۳۱‌‏-‌۳۵ او مرقوس ۱۴‏:‌۲۷‌‏-‌۳۱ او یوحنا ۱۳‏:‌۳۶‌‏-‌۳۸)', 'تاسو به زما په پاچاهی کې زما په دسترخوان خوری او چشی او په تختونو باندې به کشېنی او د اسراییلو په دولسو قبیلو باندې به حکومت کوی.» د پطروس د انکار په هکله د عیسی پېشګویی (متی ۲۶‏:‌۳۱‌‏-‌۳۵ او مرقوس ۱۴‏:‌۲۷‌‏-‌۳۱ او یوحنا ۱۳‏:‌۳۶‌‏-‌۳۸)', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25371, 'Luke 22:31', 'Luke', 22, 31, 'عیسی وویل: «ای شمعونه، ای شمعونه! واوره، شیطان وغوښتل چې تاسو ټول وازمایي، ښه او بد سره بېل کړي لکه څنګه چې بزګر د غنمو څخه بوس بېل کوي.', 'عیسی وویل: «ای شمعونه، ای شمعونه! واوره، شیطان وغوشتل چې تاسو تول وازمایی، شه او بد سره بېل کری لکه چنګه چې بزګر د غنمو چخه بوس بېل کوی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25372, 'Luke 22:32', 'Luke', 22, 32, 'خو شمعونه! ما ستا دپاره دعا کړې ده چې ایمان دې له منځه لاړ نه شي. کله چې دې توبه وویستله او بېرته ماته راوګرځېدلې، نو خپل ورونه دې قوي کړه.»', 'خو شمعونه! ما ستا دپاره دعا کرې ده چې ایمان دې له منجه لار نه شی. کله چې دې توبه وویستله او بېرته ماته راوګرجېدلې، نو خپل ورونه دې قوی کره.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25373, 'Luke 22:33', 'Luke', 22, 33, 'پطروس ځواب ورکړ: «ای استاذه! زه ستا سره زندان او مرګ ته هم تیار یم.»', 'پطروس جواب ورکر: «ای استاذه! زه ستا سره زندان او مرګ ته هم تیار یم.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25374, 'Luke 22:34', 'Luke', 22, 34, 'عیسی وویل: «ای پطروسه! زه تاته وایم چې نن شپه به د چرګ د اذان څخه مخکې درې ځلې ووایې چې ته ما نه پېژنې.» د پیسو کڅوړه، خورجین او توره', 'عیسی وویل: «ای پطروسه! زه تاته وایم چې نن شپه به د چرګ د اذان چخه مخکې درې جلې ووایې چې ته ما نه پېژنې.» د پیسو کچوره، خورجین او توره', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25375, 'Luke 22:35', 'Luke', 22, 35, 'عیسی د هغوی څخه پوښتنه وکړه: «کله چې ما تاسو بې د پیسو له کڅوړې، بې‌خورجینې او بې له څپلیو ولېږلئ، ایا په هغه وخت کې ستاسو سره د کوم شي کمی ؤ؟» هغوی ځواب ورکړ: «نه.»', 'عیسی د هغوی چخه پوشتنه وکره: «کله چې ما تاسو بې د پیسو له کچورې، بې‌خورجینې او بې له چپلیو ولېزلی، ایا په هغه وخت کې ستاسو سره د کوم شی کمی و؟» هغوی جواب ورکر: «نه.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25376, 'Luke 22:36', 'Luke', 22, 36, 'عیسی وویل: «خو اوس هرڅوک چې د پیسو کڅوړه لري هغه دې د ځان سره واخلي او همدارنګه خپل خورجین هم. او د هرچا سره چې توره نه وي، نو خپله چپنه دې خرڅه کړي او یوه توره دې واخلي.', 'عیسی وویل: «خو اوس هرچوک چې د پیسو کچوره لری هغه دې د جان سره واخلی او همدارنګه خپل خورجین هم. او د هرچا سره چې توره نه وی، نو خپله چپنه دې خرچه کری او یوه توره دې واخلی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25377, 'Luke 22:37', 'Luke', 22, 37, 'ځکه زه تاسو ته وایم چې د خدای د کلام دا لیکنه باید پوره شي چې وایي: هغه به په مجرمانو کې وشمېرل شي. ځکه هرڅه چې زما په هکله لیکل شوي دي هغه به رښتیا شي.»', 'جکه زه تاسو ته وایم چې د خدای د کلام دا لیکنه باید پوره شی چې وایی: هغه به په مجرمانو کې وشمېرل شی. جکه هرچه چې زما په هکله لیکل شوی دی هغه به رشتیا شی.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25378, 'Luke 22:38', 'Luke', 22, 38, 'شاګردانو وویل: «ګوره استاذه! زمونږ سره دلته دوه تورې دي.» عیسی ځواب ورکړ: «دا بس دي.» عیسی د زیتون په غره کې دعا کوي (متي ۲۶‏:‌۳۶‌‏-‌۴۶ او مرقوس ۱۴‏:‌۳۲‌‏-‌۴۲)', 'شاګردانو وویل: «ګوره استاذه! زمونز سره دلته دوه تورې دی.» عیسی جواب ورکر: «دا بس دی.» عیسی د زیتون په غره کې دعا کوی (متی ۲۶‏:‌۳۶‌‏-‌۴۶ او مرقوس ۱۴‏:‌۳۲‌‏-‌۴۲)', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25379, 'Luke 22:39', 'Luke', 22, 39, 'عیسی دباندې ووت او د خپل عادت له مخې د زیتون غره ته روان شو او شاګردان یې هم ورپسې لاړل.', 'عیسی دباندې ووت او د خپل عادت له مخې د زیتون غره ته روان شو او شاګردان یې هم ورپسې لارل.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25380, 'Luke 22:40', 'Luke', 22, 40, 'کله چې هغه ځای ته ورسېده، نو هغوی ته یې وویل: «دعا وکړئ چې په ازمېښت کې ونه لوېږئ.»', 'کله چې هغه جای ته ورسېده، نو هغوی ته یې وویل: «دعا وکری چې په ازمېشت کې ونه لوېزی.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25381, 'Luke 22:41', 'Luke', 22, 41, 'بیا عیسی د هغوی څخه یو څو ګامه لېرې لاړ، په ګونډو شو او دعا یې وکړه.', 'بیا عیسی د هغوی چخه یو چو ګامه لېرې لار، په ګوندو شو او دعا یې وکره.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25382, 'Luke 22:42', 'Luke', 22, 42, 'هغه وویل: «ای پلاره! که چېرې ستا رضا وي، نو دا پیاله زما څخه لېرې کړه. خو زما رضا نه، بلکې ستا رضا دې پوره شي.»', 'هغه وویل: «ای پلاره! که چېرې ستا رضا وی، نو دا پیاله زما چخه لېرې کره. خو زما رضا نه، بلکې ستا رضا دې پوره شی.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25383, 'Luke 22:43', 'Luke', 22, 43, 'بیا د اسمان څخه یوه فرښته هغه ته راښکاره شوه او هغه ته یې قوت ورکړ.', 'بیا د اسمان چخه یوه فرشته هغه ته راشکاره شوه او هغه ته یې قوت ورکر.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25384, 'Luke 22:44', 'Luke', 22, 44, 'عیسی په ډېر سخت حالت کې ؤ او په ډېر جوش سره یې دعا وکړه او خولې یې د وینو د څاڅکو په شان په ځمکه باندې څڅېدلې.', 'عیسی په دېر سخت حالت کې و او په دېر جوش سره یې دعا وکره او خولې یې د وینو د چاچکو په شان په جمکه باندې چچېدلې.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25385, 'Luke 22:45', 'Luke', 22, 45, 'کله چې عیسی د دعا څخه راپاڅېده، نو شاګردانو ته راغی او ویې لیدل چې هغوی له غمه ستومانه او ویده شوي وو.', 'کله چې عیسی د دعا چخه راپاچېده، نو شاګردانو ته راغی او ویې لیدل چې هغوی له غمه ستومانه او ویده شوی وو.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25386, 'Luke 22:46', 'Luke', 22, 46, 'هغوی ته یې وویل: «تاسو ولې ویده یئ؟ پاڅېږئ او دعا وکړئ چې په ازمېښت کې ونه لوېږئ.» د عیسی سره خیانت کول او نیول (متي ۲۶‏:‌۴۷‌‏-‌۵۶ او مرقوس ۱۴‏:‌۴۳‌‏-‌۵۰ او یوحنا ۱۸‏:‌۳‌‏-‌۱۱)', 'هغوی ته یې وویل: «تاسو ولې ویده یی؟ پاچېزی او دعا وکری چې په ازمېشت کې ونه لوېزی.» د عیسی سره خیانت کول او نیول (متی ۲۶‏:‌۴۷‌‏-‌۵۶ او مرقوس ۱۴‏:‌۴۳‌‏-‌۵۰ او یوحنا ۱۸‏:‌۳‌‏-‌۱۱)', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25387, 'Luke 22:47', 'Luke', 22, 47, 'عیسی لا خبرې کولې چې یوه ډله راغله او یهودا چې د هغو دولسو شاګردانو څخه ؤ، د هغوی څخه مخکې روان ؤ. هغه عیسی ته ورنژدې شو چې ښکل یې کړي.', 'عیسی لا خبرې کولې چې یوه دله راغله او یهودا چې د هغو دولسو شاګردانو چخه و، د هغوی چخه مخکې روان و. هغه عیسی ته ورنژدې شو چې شکل یې کری.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25388, 'Luke 22:48', 'Luke', 22, 48, 'خو عیسی وویل: «ای یهودا! ایا په ښکلولو سره د انسان زوی دښمنانو ته په لاس ورکوې؟»', 'خو عیسی وویل: «ای یهودا! ایا په شکلولو سره د انسان زوی دشمنانو ته په لاس ورکوې؟»', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25389, 'Luke 22:49', 'Luke', 22, 49, 'کله چې د عیسی شاګردانو ولیدل چې څه کیږي، نو ویې ویل: «استاذه! ایا په تورو یې ووهو؟»', 'کله چې د عیسی شاګردانو ولیدل چې چه کیزی، نو ویې ویل: «استاذه! ایا په تورو یې ووهو؟»', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25390, 'Luke 22:50', 'Luke', 22, 50, 'د هغوی څخه یو تن د لوی کاهن په نوکر ګوزار وکړ او د هغه ښي غوږ یې پرې کړ.', 'د هغوی چخه یو تن د لوی کاهن په نوکر ګوزار وکر او د هغه شی غوز یې پرې کر.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
