(25444, 'John 16:1', 'John', 16, 1, 'ما دا شیان تاسو ته د دې دپاره وویل چې ایمان له لاسه ورنه کړئ.', 'ما دا شیان تاسو ته د دې دپاره وویل چې ایمان له لاسه ورنه کری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25445, 'John 16:2', 'John', 16, 2, 'هغوی به تاسو د کنیسو نه وشړي او داسې وخت به راشي څوک چې تاسو ووژني، نو هغوی به ګومان کوي چې په دې کار سره یې خدای ته خدمت کړی دی.', 'هغوی به تاسو د کنیسو نه وشری او داسې وخت به راشی چوک چې تاسو ووژنی، نو هغوی به ګومان کوی چې په دې کار سره یې خدای ته خدمت کری دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25446, 'John 16:3', 'John', 16, 3, 'هغوی به تاسو سره داسې کارونه کوي، ځکه چې هغوی نه پلار پېژني او نه ما.', 'هغوی به تاسو سره داسې کارونه کوی، جکه چې هغوی نه پلار پېژنی او نه ما.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25447, 'John 16:4', 'John', 16, 4, 'دا شیان مې د دې دپاره تاسو ته وویل چې کله د هغوی د واک وخت راورسیږي، نو تاسو ته به زما خبرې در په یاد شي. د روح القدس کار ما دا شیان په پیل کې تاسو ته ونه ویل ځکه زه په خپله تاسو سره وم،', 'دا شیان مې د دې دپاره تاسو ته وویل چې کله د هغوی د واک وخت راورسیزی، نو تاسو ته به زما خبرې در په یاد شی. د روح القدس کار ما دا شیان په پیل کې تاسو ته ونه ویل جکه زه په خپله تاسو سره وم،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25448, 'John 16:5', 'John', 16, 5, 'خو زه اوس هغه چاته ورځم چې زه یې رالېږلی یم او تاسو یو هم زما نه دا پوښتنه نه کوئ چې ته چېرته ځې؟', 'خو زه اوس هغه چاته ورجم چې زه یې رالېزلی یم او تاسو یو هم زما نه دا پوشتنه نه کوی چې ته چېرته جې؟', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25449, 'John 16:6', 'John', 16, 6, 'ما چې تاسو ته کوم څه وویل په هغې باندې ستاسو زړونه غمجن شول.', 'ما چې تاسو ته کوم چه وویل په هغې باندې ستاسو زرونه غمجن شول.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25450, 'John 16:7', 'John', 16, 7, 'خو زه تاسو ته حقیقت وایم چې زما تګ ستاسو دپاره ښه دی، ځکه که زه لاړ نه شم نو تاسو ته به مرسته کوونکی رانه شي. خو که زه لاړ شم، نو هغه به تاسو ته درولېږم.', 'خو زه تاسو ته حقیقت وایم چې زما تګ ستاسو دپاره شه دی، جکه که زه لار نه شم نو تاسو ته به مرسته کوونکی رانه شی. خو که زه لار شم، نو هغه به تاسو ته درولېزم.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25451, 'John 16:8', 'John', 16, 8, 'کله چې هغه راشي، نو د دې نړۍ خلکو ته به د ګناه او د خدای د عدالت او قضاوت په هکله حقیقت ښکاره کړي.', 'کله چې هغه راشی، نو د دې نری خلکو ته به د ګناه او د خدای د عدالت او قضاوت په هکله حقیقت شکاره کری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25452, 'John 16:9', 'John', 16, 9, 'د نړۍ خلک د ګناه په هکله غلط فکر لري، ځکه چې هغوی په ما باندې ایمان نه راوړي.', 'د نری خلک د ګناه په هکله غلط فکر لری، جکه چې هغوی په ما باندې ایمان نه راوری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25453, 'John 16:10', 'John', 16, 10, 'هغوی د عدالت په هکله غلط فکر لري، ځکه چې زه پلار ته ځم او نور به مې ونه وینئ،', 'هغوی د عدالت په هکله غلط فکر لری، جکه چې زه پلار ته جم او نور به مې ونه وینی،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25454, 'John 16:11', 'John', 16, 11, 'هغوی د خدای د قضاوت په هکله هم غلط فکر لري، ځکه چې د دې نړۍ واکمن لا پخوا محکوم کړای شوی دی.', 'هغوی د خدای د قضاوت په هکله هم غلط فکر لری، جکه چې د دې نری واکمن لا پخوا محکوم کرای شوی دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25455, 'John 16:12', 'John', 16, 12, 'ډېرې نورې خبرې دي چې باید تاسو ته یې وکړم خو اوس یې تاسو د اورېدلو توان نه لرئ.', 'دېرې نورې خبرې دی چې باید تاسو ته یې وکرم خو اوس یې تاسو د اورېدلو توان نه لری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25456, 'John 16:13', 'John', 16, 13, 'خو کله چې د حقیقت روح راشي نو تاسو ته به د حقیقت طرف ته بوځي. هغه به له خپله ځانه خبرې نه کوي بلکې څه چې هغه اوري هغه به وایي او په راتلونکي کې چې کوم څه کیږي تاسو به ورباندې خبر کړي.', 'خو کله چې د حقیقت روح راشی نو تاسو ته به د حقیقت طرف ته بوجی. هغه به له خپله جانه خبرې نه کوی بلکې چه چې هغه اوری هغه به وایی او په راتلونکی کې چې کوم چه کیزی تاسو به ورباندې خبر کری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25457, 'John 16:14', 'John', 16, 14, 'هغه چې زما نه کوم تعلیم تر‌لاسه کوي، نو تاسو به ورباندې خبروي او په دې ډول به زما جلال ښکاره کوي.', 'هغه چې زما نه کوم تعلیم تر‌لاسه کوی، نو تاسو به ورباندې خبروی او په دې دول به زما جلال شکاره کوی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25458, 'John 16:15', 'John', 16, 15, 'څه چې د پلار سره دي هغه زما دي، نو په دې خاطر ما وویل هغه تعلیم چې روح القدس یې زما نه حاصلوي، تاسو به ورباندې خبروي.» ستاسو غم به په خوشحالۍ بدل شي', 'چه چې د پلار سره دی هغه زما دی، نو په دې خاطر ما وویل هغه تعلیم چې روح القدس یې زما نه حاصلوی، تاسو به ورباندې خبروی.» ستاسو غم به په خوشحالی بدل شی', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25459, 'John 16:16', 'John', 16, 16, 'عیسی خپلو شاګردانو ته وویل: «د لږ وخت دپاره به تاسو نور ما نه وینئ، خو لږه موده وروسته به مې بیا ووینئ.»', 'عیسی خپلو شاګردانو ته وویل: «د لز وخت دپاره به تاسو نور ما نه وینی، خو لزه موده وروسته به مې بیا ووینی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25460, 'John 16:17', 'John', 16, 17, 'ځینو شاګردانو یو بل ته سره وویل: «د دې خبرې نه د هغه مقصد څه دی چې وایي: ‹د لږ وخت دپاره به تاسو ما ونه وینئ، خو لږه موده وروسته به مې ووینئ› او ‹دا ځکه چې زه پلار ته ورځم؟›»', 'جینو شاګردانو یو بل ته سره وویل: «د دې خبرې نه د هغه مقصد چه دی چې وایی: ‹د لز وخت دپاره به تاسو ما ونه وینی، خو لزه موده وروسته به مې ووینی› او ‹دا جکه چې زه پلار ته ورجم؟›»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_16_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833);